from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    enclosed = set()
    # Zero components that cannot reach the edge are the interiors of closed outlines.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            edge = False
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                    edge = True
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and not seen[nx][ny]:
                        seen[nx][ny] = True
                        q.append((nx, ny))
            if not edge:
                enclosed.update(cells)
    if not enclosed:
        return out
    # An outline component is active when it borders an enclosed region.
    seen1 = [[False] * w for _ in range(h)]
    active = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen1[r][c]:
                continue
            q = deque([(r, c)])
            seen1[r][c] = True
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for dx in (-1,0,1):
                    for dy in (-1,0,1):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and not seen1[nx][ny]:
                            seen1[nx][ny] = True
                            q.append((nx, ny))
            borders_interior = any((x+dx, y+dy) in enclosed
                                   for x,y in comp
                                   for dx in (-1,0,1) for dy in (-1,0,1)
                                   if (dx or dy) and 0 <= x+dx < h and 0 <= y+dy < w)
            if borders_interior:
                active.update(comp)
    # Color one-cell diagonal/orthogonal bands: 3 inside closed outlines, 2 outside.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            near_active = any((r+dr, c+dc) in active
                              for dr in (-1,0,1) for dc in (-1,0,1)
                              if (dr or dc) and 0 <= r+dr < h and 0 <= c+dc < w)
            if near_active:
                out[r][c] = 3 if (r,c) in enclosed else 2
    return out
